def _build_shift_table(pattern: str) -> dict[str, int]:
    """
    Build the bad-character shift table for ``pattern``.

    For every character in the pattern except the last one, the table
    stores the distance from that character to the end of the pattern.
    Characters that do not appear in the pattern fall back to ``len(pattern)``
    at lookup time.

    >>> _build_shift_table("abcab")
    {'a': 1, 'b': 3, 'c': 2}
    >>> _build_shift_table("a")
    {}
    >>> _build_shift_table("")
    {}
    >>> _build_shift_table("aaaa")
    {'a': 1}
    """
    pattern_length = len(pattern)
    table: dict[str, int] = {}
    for index in range(pattern_length - 1):
        table[pattern[index]] = pattern_length - 1 - index
    return table

def binary_xor(a: int, b: int) -> str:
    if not isinstance(a, int) or not isinstance(b, int):
        raise TypeError("inputs must be integers")
    if a < 0 or b < 0:
        raise ValueError("inputs must be non-negative integers")

    max_len = max(a.bit_length(), b.bit_length())
    return f"0b{(a ^ b):0{max_len}b}"

def binary_or(a: int, b: int) -> str:
    if not isinstance(a, int) or not isinstance(b, int):
        raise TypeError("inputs must be integers")
    if a < 0 or b < 0:
        raise ValueError("inputs must be non-negative integers")
    max_len = max(a.bit_length(), b.bit_length())
    return f"0b{(a | b):0{max_len}b}"

def add_key_to_lexicon(
    lexicon: dict[str, str], curr_string: str, index: int, last_match_id: str
) -> None:
    """
    Adds new strings (curr_string + "0",  curr_string + "1") to the lexicon
    """
    lexicon.pop(curr_string)
    lexicon[curr_string + "0"] = last_match_id

    if math.log2(index).is_integer():
        for curr_key, value in lexicon.items():
            lexicon[curr_key] = f"0{value}"

    lexicon[curr_string + "1"] = bin(index)[2:]

def write_file_binary(file_path: str, to_write: str) -> None:
    """
    Writes given to_write string (should only consist of 0's and 1's) as bytes in the
    file
    """
    byte_length = 8
    try:
        with open(file_path, "wb") as opened_file:
            result_byte_array = [
                to_write[i : i + byte_length]
                for i in range(0, len(to_write), byte_length)
            ]

            if len(result_byte_array[-1]) % byte_length == 0:
                result_byte_array.append("10000000")
            else:
                result_byte_array[-1] += "1" + "0" * (
                    byte_length - len(result_byte_array[-1]) - 1
                )

            for elem in result_byte_array:
                opened_file.write(int(elem, 2).to_bytes(1, byteorder="big"))
    except OSError:
        print("File not accessible")
        sys.exit()

