def solution():
    """
    Return the solution of the problem.
    >>> solution()
    296962999629
    """
    prime_list = [n for n in range(1001, 10000, 2) if is_prime(n)]
    candidates = []

    for number in prime_list:
        tmp_numbers = []

        for prime_member in permutations(list(str(number))):
            prime = int("".join(prime_member))

            if prime % 2 == 0:
                continue

            if search(prime, prime_list):
                tmp_numbers.append(prime)

        tmp_numbers.sort()
        if len(tmp_numbers) >= 3:
            candidates.append(tmp_numbers)

    passed = []
    for candidate in candidates:
        length = len(candidate)
        found = False

        for i in range(length):
            for j in range(i + 1, length):
                for k in range(j + 1, length):
                    if (
                        abs(candidate[i] - candidate[j])
                        == abs(candidate[j] - candidate[k])
                        and len({candidate[i], candidate[j], candidate[k]}) == 3
                    ):
                        passed.append(
                            sorted([candidate[i], candidate[j], candidate[k]])
                        )
                        found = True

                    if found:
                        break
                if found:
                    break
            if found:
                break

    answer = set()
    for seq in passed:
        answer.add("".join([str(i) for i in seq]))

    return max(int(x) for x in answer)

def solution(filename: str = "input.txt") -> int:
    """
    Returns the minimal path sum in the matrix from the file, by starting in any cell
    in the left column and finishing in any cell in the right column,
    and only moving up, down, and right

    >>> solution("test_matrix.txt")
    994
    """

    with open(os.path.join(os.path.dirname(__file__), filename)) as input_file:
        matrix = [
            [int(element) for element in line.split(",")]
            for line in input_file.readlines()
        ]

    rows = len(matrix)
    cols = len(matrix[0])

    minimal_path_sums = [[-1 for _ in range(cols)] for _ in range(rows)]
    for i in range(rows):
        minimal_path_sums[i][0] = matrix[i][0]

    for j in range(1, cols):
        for i in range(rows):
            minimal_path_sums[i][j] = minimal_path_sums[i][j - 1] + matrix[i][j]

        for i in range(1, rows):
            minimal_path_sums[i][j] = min(
                minimal_path_sums[i][j], minimal_path_sums[i - 1][j] + matrix[i][j]
            )

        for i in range(rows - 2, -1, -1):
            minimal_path_sums[i][j] = min(
                minimal_path_sums[i][j], minimal_path_sums[i + 1][j] + matrix[i][j]
            )

    return min(minimal_path_sums_row[-1] for minimal_path_sums_row in minimal_path_sums)

def solution(number: int = 10_000_000) -> int:
    """
    Returns how many starting numbers below `number` will arrive at 89
    in the digit-square chain.

    Uses digit DP so the count is computed in O(k * d_max * 10) time —
    roughly 40 000 operations for number = 10^7 — instead of iterating
    all `number` values explicitly.

    Key observations:
    1. For any n < number, digit_square_sum(n) ≤ num_digits * 81,
       so chain endpoints can be precomputed for that small range only.
    2. A digit DP over the decimal digits of (number - 1) counts how many
       integers in [0, number-1] have each possible digit-square sum,
       grouping by whether the prefix is still bounded ("tight") or free.
       Integers whose digit-square sum equals 0 are exactly 0 itself.

    >>> solution(100)
    80

    >>> solution(10_000_000)
    8581146
    """
    num_digits = len(str(number - 1)) if number > 1 else 1
    limit = num_digits * 81 + 1  # max possible digit-square sum + 1

    def digit_square_sum(n: int) -> int:
        total = 0
        while n:
            total += (n % 10) ** 2
            n //= 10
        return total

    # Precompute whether each value 1..limit-1 eventually reaches 89.
    # All intermediate chain values stay below limit because the digit-square
    # sum of any k-digit number is at most k * 81 = limit - 1.
    ends_at_89 = bytearray(limit)
    for i in range(1, limit):
        n = i
        while n not in (1, 89):
            n = digit_square_sum(n)
        ends_at_89[i] = n == 89

    # Digit DP over the decimal digits of (number - 1).
    # Treating shorter numbers as zero-padded strings (e.g. 7 → "0000007")
    # is safe because 0^2 = 0 contributes nothing to the digit-square sum.
    # dp_tight[s] / dp_free[s] = count of digit sequences whose running
    # digit-square sum is s and whose prefix is still ≤ / already < the
    # corresponding prefix of (number - 1).
    digits = [int(d) for d in str(number - 1)] if number > 1 else [0]

    dp_tight: dict[int, int] = {0: 1}
    dp_free: dict[int, int] = {}

    for lim in digits:
        new_tight: dict[int, int] = {}
        new_free: dict[int, int] = {}

        for dss, cnt in dp_tight.items():
            for d in range(lim + 1):
                new_val = dss + d * d
                if new_val < limit:
                    if d == lim:
                        new_tight[new_val] = new_tight.get(new_val, 0) + cnt
                    else:
                        new_free[new_val] = new_free.get(new_val, 0) + cnt

        for dss, cnt in dp_free.items():
            for d in range(10):
                new_val = dss + d * d
                if new_val < limit:
                    new_free[new_val] = new_free.get(new_val, 0) + cnt

        dp_tight, dp_free = new_tight, new_free

    # Sum counts for all digit-square sums that end at 89.
    # dss == 0 corresponds to the number 0, which is excluded.
    return sum(
        cnt
        for dss, cnt in (*dp_tight.items(), *dp_free.items())
        if 0 < dss < limit and ends_at_89[dss]
    )

def generate_primes(max_num: int) -> list[int]:
    """
    Calculates the list of primes up to and including `max_num`.

    >>> generate_primes(6)
    [2, 3, 5]
    """
    are_primes = [True] * (max_num + 1)
    are_primes[0] = are_primes[1] = False
    for i in range(2, isqrt(max_num) + 1):
        if are_primes[i]:
            for j in range(i * i, max_num + 1, i):
                are_primes[j] = False

    return [prime for prime, is_prime in enumerate(are_primes) if is_prime]

def calculate_prime_numbers(max_number: int) -> list[int]:
    """
    Returns prime numbers below max_number

    >>> calculate_prime_numbers(10)
    [2, 3, 5, 7]
    """

    is_prime = [True] * max_number
    for i in range(2, isqrt(max_number - 1) + 1):
        if is_prime[i]:
            for j in range(i**2, max_number, i):
                is_prime[j] = False

    return [i for i in range(2, max_number) if is_prime[i]]

