def decrypt_message(key: str, message: str) -> str:
    """
    >>> decrypt_message('LFWOAYUISVKMNXPBDCRJTQEGHZ', 'Ilcrism Olcvs')
    'Harshil Darji'
    """
    return translate_message(key, message, "decrypt")

def translate_message(key: str, message: str, mode: str) -> str:
    translated = ""
    chars_a = LETTERS
    chars_b = key

    if mode == "decrypt":
        chars_a, chars_b = chars_b, chars_a

    for symbol in message:
        if symbol.upper() in chars_a:
            sym_index = chars_a.find(symbol.upper())
            if symbol.isupper():
                translated += chars_b[sym_index].upper()
            else:
                translated += chars_b[sym_index].lower()
        else:
            translated += symbol

    return translated

def _normalize_key(key: str) -> str:
    k = "".join(ch for ch in key.upper() if ch.isalpha())
    if not k:
        raise ValueError("Key must be a non-empty alphabetic string")
    return k

def _column_order(key: str) -> list[int]:
    # Stable sort by character then original index to handle duplicates
    indexed = list(enumerate(key))
    return [
