def topo(g, ind=None, q=None) -> None:
    """
    Perform a topological sort on a directed acyclic graph.

    >>> topo({1: [2, 3], 2: [4], 3: [4], 4: []})
    1
    2
    3
    4
    """
    if q is None:
        q = [1]
    if ind is None:
        ind = [0] * (len(g) + 1)  # SInce oth Index is ignored
        for u in g:
            for v in g[u]:
                ind[v] += 1
        q = deque()
        for i in g:
            if ind[i] == 0:
                q.append(i)
    if len(q) == 0:
        return
    v = q.popleft()
    print(v)
    for w in g[v]:
        ind[w] -= 1
        if ind[w] == 0:
            q.append(w)
    topo(g, ind, q)

